CREATE TABLE IF NOT EXISTS ai_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,agent_name TEXT NOT NULL,model TEXT,task TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',confidence NUMERIC(5,4),input_refs JSONB NOT NULL DEFAULT '{}'::jsonb,output JSONB,latency_ms INTEGER,cost_micros BIGINT,error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);CREATE INDEX IF NOT EXISTS ai_runs_tenant_idx ON ai_runs(tenant_id,created_at DESC);